	-- UI_Options.lua
	["Canal dédié"] = "Canale dedicato",
	["Gestion liste token"] = "Gestisci lista token",
	["Ouvre la liste des autres comptes Battle.net autorisés sur le canal dédié, pour voir leurs personnages et révoquer une autorisation."] = "Apre la lista degli altri account Battle.net autorizzati sul canale dedicato, per vederne i personaggi e revocare un'autorizzazione.",
	["Compte WoW de ce personnage"] = "Account WoW di questo personaggio",
	["Compte WoW : non renseigné."] = "Account WoW: non indicato.",
	["Compte WoW de ce personnage : %s."] = "Account WoW di questo personaggio: %s.",
	["Cochez « Personnages disponibles : regrouper par compte » pour voir les comptes."] = "Spunta «Personaggi disponibili: raggruppa per account» per vedere gli account.",
	["Nom du compte WoW sur lequel vous jouez ce personnage (ex. WoW1). WoW ne le donne pas aux addons : à saisir une fois par personnage. Sert au regroupement par compte des personnages disponibles ; partagé avec vos autres Polypode. Enregistré à Entrée ou en quittant le champ ; Échap annule ; vide = aucun compte. Même réglage que Alt + clic sur un personnage dans la fenêtre Polypode."] = "Nome dell'account WoW su cui giochi questo personaggio (es. WoW1). WoW non lo fornisce agli addon: inseriscilo una volta per personaggio. Serve a raggruppare per account i personaggi disponibili; condiviso con gli altri tuoi Polypode. Salvato con Invio o uscendo dal campo; Esc annulla; vuoto = nessun account. Stessa impostazione di Alt + clic su un personaggio nella finestra di Polypode.",
	["Mode solo"] = "Modalità solo",
	["Pour jouer un seul personnage : la fenêtre Polypode ne garde que « Personnages disponibles » (agrandi, fenêtre un peu plus étroite), sans les cadres d'équipe. Glissez votre personnage hors de la liste pour en faire une barre flottante, avec les boutons des modules (Suivi sur tous les personnages). Même case que « Solo » dans la fenêtre. Réglage propre à ce personnage."] = "Per giocare un solo personaggio: la finestra di Polypode conserva solo «Personaggi disponibili» (ingrandito, finestra un po' più stretta), senza i riquadri della squadra. Trascina il tuo personaggio fuori dalla lista per farne una barra mobile, con i pulsanti dei moduli (Monitoraggio su tutti i personaggi). Stessa casella di «Solo» nella finestra. Impostazione propria di questo personaggio.",
	["Afficher l'icône de minimap"] = "Mostra l'icona della minimappa",
	["Affiche le bouton Polypode autour de la minimap (équivalent de /poly minimap)."] = "Mostra il pulsante di Polypode attorno alla minimappa (come /poly minimap).",
	["Mode debug"] = "Modalità debug",
	["Affiche dans le chat les messages de diagnostic de Polypode (synchro, invitations...). Réglage propre à ce personnage (équivalent de /poly debug)."] = "Mostra nella chat i messaggi diagnostici di Polypode (sincronizzazione, inviti...). Impostazione propria di questo personaggio (come /poly debug).",
	["Attaquer après l'assistance"] = "Attacca dopo l'assistenza",
	["Le raccourci « Assister le leader » lance aussi l'attaque automatique (/startattack) sur la cible prise, si elle est hostile. Décoché : prend seulement la cible du leader. Réglage propre à ce personnage."] = "La scorciatoia «Assisti il leader» avvia anche l'attacco automatico (/startattack) sul bersaglio preso, se ostile. Non spuntata: prende solo il bersaglio del leader. Impostazione propria di questo personaggio.",
	["Accepter automatiquement les quêtes"] = "Accetta automaticamente le missioni",
	["Quand le leader de l'équipe accepte une quête, ce personnage l'accepte aussi dès qu'elle lui est proposée (PNJ ouvert, jusqu'à 30 secondes après). Sur le leader, annonce ses quêtes acceptées au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra accetta una missione, anche questo personaggio la accetta appena gli viene proposta (PNG aperto, fino a 30 secondi dopo). Sul leader, annuncia al gruppo le missioni accettate. Impostazione propria di questo personaggio.",
	["Valider automatiquement les quêtes"] = "Completa automaticamente le missioni",
	["Quand le leader de l'équipe rend une quête (« Continuer » puis « Terminer la quête »), ce personnage la rend aussi, avec le même choix de récompense, dès que le PNJ est ouvert (jusqu'à 60 secondes après). Sur le leader, annonce ses validations au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra consegna una missione («Continua» e poi «Completa la missione»), anche questo personaggio la consegna, con la stessa ricompensa scelta, appena il PNG è aperto (fino a 60 secondi dopo). Sul leader, annuncia al gruppo le consegne. Impostazione propria di questo personaggio.",
	["Suivre les dialogues de PNJ du leader"] = "Segui i dialoghi con i PNG del leader",
	["Quand le leader de l'équipe choisit une quête (disponible ou à rendre) ou une option dans le dialogue d'un PNJ, ce personnage fait le même choix si son dialogue avec le PNJ est ouvert ; quand le leader ferme DialogueUI, il le ferme aussi. L'acceptation ou la validation automatique prend ensuite le relais. Sur le leader, annonce ses choix au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra sceglie una missione (disponibile o da consegnare) o un'opzione nel dialogo di un PNG, questo personaggio fa la stessa scelta se il suo dialogo con il PNG è aperto; quando il leader chiude DialogueUI, lo chiude anche lui. Poi subentra l'accettazione o il completamento automatico. Sul leader, annuncia al gruppo le scelte. Impostazione propria di questo personaggio.",
	["Passer automatiquement les cinématiques"] = "Salta automaticamente i filmati",
	["Quand le leader de l'équipe passe une cinématique ou une vidéo, ce personnage la passe aussi (dès qu'elle s'affiche, jusqu'à 15 secondes après). Sur le leader, annonce ses cinématiques passées au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra salta un filmato o un video, anche questo personaggio lo salta (appena appare, fino a 15 secondi dopo). Sul leader, annuncia al gruppo i filmati saltati. Impostazione propria di questo personaggio.",
	["Prendre automatiquement le vol du leader"] = "Prendi automaticamente il volo del leader",
	["Quand le leader de l'équipe prend un vol chez un maître de vol, ce personnage prend le même vol si sa carte de vol est ouverte et qu'il connaît la destination. Sur le leader, annonce ses vols au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra prende un volo da un maestro di volo, questo personaggio prende lo stesso volo se la sua mappa di volo è aperta e conosce la destinazione. Sul leader, annuncia al gruppo i voli. Impostazione propria di questo personaggio.",
	["Entrer automatiquement en instance (gouffre, portail)"] = "Entra automaticamente nelle istanze (scorribanda, portale)",
	["Quand le leader de l'équipe choisit le palier d'un gouffre, ce personnage choisit le même si sa fenêtre de palier est ouverte ; quand le leader vote la sortie du gouffre, il vote « Oui » aussi (jusqu'à 30 secondes après) ; quand le leader confirme l'entrée par un portail d'instance, il confirme aussi. Sur le leader, annonce ces actions au groupe. Réglage propre à ce personnage."] = "Quando il leader della squadra sceglie il livello di una scorribanda, questo personaggio sceglie lo stesso se la sua finestra dei livelli è aperta; quando il leader vota per uscire dalla scorribanda, vota anche lui «Sì» (fino a 30 secondi dopo); quando il leader conferma l'ingresso da un portale d'istanza, conferma anche lui. Sul leader, annuncia queste azioni al gruppo. Impostazione propria di questo personaggio.",
	["Volume envoyé"] = "Volume inviato",
	["Volume principal (en %) que le raccourci « Envoyer le volume à l'équipe » applique aux autres membres quand ce personnage est le leader. Réglage propre à ce personnage."] = "Volume principale (in %) che la scorciatoia «Invia il volume alla squadra» applica agli altri membri quando questo personaggio è il leader. Impostazione propria di questo personaggio.",
	["Suivre le son du leader"] = "Segui l'audio del leader",
	["Applique à ce personnage le volume envoyé par le leader de l'équipe et la coupure ou le rétablissement du son (raccourcis du leader). Décoché : ce client garde son propre son. Réglage propre à ce personnage."] = "Applica a questo personaggio il volume inviato dal leader della squadra e la disattivazione o il ripristino dell'audio (scorciatoie del leader). Non spuntata: questo client mantiene il proprio audio. Impostazione propria di questo personaggio.",
	["Personnages disponibles : regrouper par compte"] = "Personaggi disponibili: raggruppa per account",
	["Dans la fenêtre Polypode, range les personnages disponibles sous un en-tête par compte WoW, repliable d'un clic. WoW ne donne pas le nom du compte WoW aux addons : renseignez-le sur chaque personnage (champ ci-dessous, ou Alt + clic sur un personnage dans la fenêtre) ; les autres vont dans « Compte non renseigné ». Réglage propre à ce personnage."] = "Nella finestra di Polypode, ordina i personaggi disponibili sotto un'intestazione per account WoW, comprimibile con un clic. WoW non fornisce il nome dell'account WoW agli addon: indicalo su ogni personaggio (campo qui sotto, o Alt + clic su un personaggio nella finestra); gli altri vanno in «Account non indicato». Impostazione propria di questo personaggio.",
	["Ouvre la fenêtre où coller la liste de vos personnages (produite par Polypode\\tools\\import_bnet.py, voir tools\\IMPORT_BNET.md) pour les ajouter au roster sans les connecter un par un. Aussi par la commande /poly import."] = "Apre la finestra in cui incollare la lista dei tuoi personaggi (generata da Polypode\\tools\\import_bnet.py, vedi tools\\IMPORT_BNET.md) per aggiungerli alla lista senza collegarli uno a uno. Anche con il comando /poly import.",
	["Groupage automatique de l'équipe"] = "Gruppo automatico della squadra",
	["Leader : invite automatiquement dans son groupe les membres de l'équipe qui se connectent (ou déjà connectés quand il se connecte). Membre : accepte automatiquement l'invitation de groupe du leader d'une de ses équipes. Réglage propre à ce personnage."] = "Leader: invita automaticamente nel suo gruppo i membri della squadra che si collegano (o già collegati quando si collega). Membro: accetta automaticamente l'invito di gruppo del leader di una delle sue squadre. Impostazione propria di questo personaggio.",
	["Alerte quand un membre ne suit plus"] = "Avviso quando un membro smette di seguire",
	["Membre : quand il arrête de suivre le leader de l'équipe (obstacle, saut, distance, mouvement manuel...), il le signale au leader. Leader : affiche « X ne vous suit plus. » à l'écran avec un son d'alerte. Réglage propre à ce personnage, à cocher sur le leader et les membres."] = "Membro: quando smette di seguire il leader della squadra (ostacolo, salto, distanza, movimento manuale...), lo segnala al leader. Leader: mostra «X non ti segue più.» sullo schermo con un suono d'allarme. Impostazione propria di questo personaggio, da spuntare sul leader e sui membri.",
	["Barre d'équipe : niveau, niveau d'objet et progression"] = "Barra della squadra: livello, livello oggetto e progresso",
	["Dans la liste de la barre flottante d'équipe, affiche à gauche de chaque personnage son niveau, le pourcentage d'avancement dans ce niveau (sauf au niveau maximum) et son niveau d'objet équipé. Infos envoyées par le Polypode de chaque personnage (« ? » tant qu'elles ne sont pas reçues). Réglage propre à ce personnage."] = "Nella lista della barra mobile della squadra, mostra a sinistra di ogni personaggio il suo livello, la percentuale di avanzamento in quel livello (tranne al livello massimo) e il suo livello oggetto equipaggiato. Informazioni inviate dal Polypode di ogni personaggio («?» finché non sono ricevute). Impostazione propria di questo personaggio.",
	["Barre d'équipe : barre de vie des membres"] = "Barra della squadra: barra della salute dei membri",
	["Dans la liste de la barre flottante d'équipe, souligne chaque membre groupé d'une fine barre de vie. Décochée : seul le libellé d'état (hors groupe, mort, loin...) reste. Réglage propre à ce personnage."] = "Nella lista della barra mobile della squadra, sottolinea ogni membro in gruppo con una sottile barra della salute. Non spuntata: resta solo l'indicazione di stato (fuori gruppo, morto, lontano...). Impostazione propria di questo personaggio.",
	["Barre d'équipe : clignoter si la durabilité est faible"] = "Barra della squadra: lampeggia se la resistenza è bassa",
	["Dans la liste de la barre flottante d'équipe, fait clignoter en rouge un personnage dont la pièce d'équipement la plus usée est sous le seuil de durabilité ci-dessous. Durabilité envoyée par le Polypode de chaque personnage. Réglage propre à ce personnage."] = "Nella lista della barra mobile della squadra, fa lampeggiare in rosso un personaggio il cui pezzo d'equipaggiamento più usurato è sotto la soglia di resistenza qui sotto. Resistenza inviata dal Polypode di ogni personaggio. Impostazione propria di questo personaggio.",
	["Barre d'équipe : seuil de durabilité"] = "Barra della squadra: soglia di resistenza",
	["Un personnage clignote dans la barre flottante d'équipe quand la durabilité de sa pièce la plus usée est inférieure à ce pourcentage (de 5 à 95 %, par pas de 5). Réglage propre à ce personnage."] = "Un personaggio lampeggia nella barra mobile della squadra quando la resistenza del suo pezzo più usurato è inferiore a questa percentuale (dal 5 al 95 %, a passi di 5). Impostazione propria di questo personaggio.",
	["Barre d'équipe : boutons des modules"] = "Barra della squadra: pulsanti dei moduli",
	["Affiche contre la barre flottante d'équipe une colonne de petits boutons reprenant ceux des modules (Data, Photo, Profils, Suivi... selon les addons installés) : trois premières lettres, même clic et même infobulle que dans la fenêtre Polypode. Chaque bouton se choisit dans la liste dessous. Réglage propre à ce personnage."] = "Mostra accanto alla barra mobile della squadra una colonna di piccoli pulsanti che riprendono quelli dei moduli (Data, Foto, Profili, Monitoraggio... secondo gli addon installati): prime tre lettere, stesso clic e stesso suggerimento della finestra di Polypode. Ogni pulsante si sceglie nell'elenco sotto. Impostazione propria di questo personaggio.",
	["Barre d'équipe : côté des boutons"] = "Barra della squadra: lato dei pulsanti",
	["À gauche"] = "A sinistra",
	["À droite"] = "A destra",
	["Horizontal"] = "Orizzontale",
	["Place des boutons des modules : colonne à gauche ou à droite de la barre flottante d'équipe, ou rangée horizontale au-dessus. Barre réduite : colonne sous l'icône (à gauche, à droite), ou rangée à sa droite (horizontal). Réglage propre à ce personnage."] = "Posizione dei pulsanti dei moduli: colonna a sinistra o a destra della barra mobile della squadra, oppure riga orizzontale sopra. Barra ridotta: colonna sotto l'icona (sinistra, destra), oppure riga alla sua destra (orizzontale). Impostazione propria di questo personaggio.",
	["Barre d'équipe : réduite à l'icône"] = "Barra della squadra: ridotta all'icona",
	["La barre flottante d'équipe ne garde que l'icône Polypode, dans un cadre de la taille d'un bouton de module (nom, liste des personnages et croix masqués) ; les boutons des modules sont dessous en colonne, ou à droite en rangée avec « Horizontal ». Icône : clic = fenêtre Polypode, clic droit = options, glisser = déplacer, Alt + clic = figer. Réglage propre à ce personnage."] = "La barra mobile della squadra conserva solo l'icona di Polypode, in un riquadro grande quanto un pulsante di modulo (nome, lista dei personaggi e croce nascosti); i pulsanti dei moduli sono sotto in colonna, o a destra in riga con «Orizzontale». Icona: clic = finestra di Polypode, clic destro = opzioni, trascina = sposta, Alt + clic = blocca. Impostazione propria di questo personaggio.",
	["Options de Polypode"] = "Opzioni di Polypode",
